-- Insert Quiz Questions for Lesson: The Building Blocks

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'building-blocks' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson building-blocks not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a trigger do?', 
    '["Pauses the workflow","Starts the workflow","Ends the workflow","Deletes the contact"]'::jsonb,
    'Starts the workflow',
    'The trigger is the event that starts the workflow. Examples include form submissions, appointment bookings, tag additions, and payments received.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the purpose of a filter?', 
    '["To send emails","To limit which events or contacts qualify for the workflow","To pause the workflow","To end the workflow"]'::jsonb,
    'To limit which events or contacts qualify for the workflow',
    'A filter narrows the trigger so the workflow only responds to specific events or contacts, preventing unwanted workflow runs.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the difference between Draft and Published?', 
    '["There is no difference","Draft does not respond to real triggers; Published can process qualifying contacts","Draft is more expensive","Published cannot be edited"]'::jsonb,
    'Draft does not respond to real triggers; Published can process qualifying contacts',
    'Draft workflows are saved but inactive. Published workflows actively process contacts who meet the trigger conditions.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


