-- Insert Quiz Questions for Lesson: Map the Process Before Building

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'map-process-before-building' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson map-process-before-building not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the five planning questions?', 
    '["Who, what, when, where, why","What event starts it, who qualifies, what happens, who owns follow-up, how to prove it worked","How much, how many, how long, how often, how far","What color, what size, what shape, what weight, what material"]'::jsonb,
    'What event starts it, who qualifies, what happens, who owns follow-up, how to prove it worked',
    'The five planning questions are: What event starts the process? Which contact qualifies? What should happen? Who owns the next action? How will you prove it worked?', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the recommended workflow naming pattern?', 
    '["Random words","SOURCE – PURPOSE – MAIN RESULT","Your name and date","Numbers only"]'::jsonb,
    'SOURCE – PURPOSE – MAIN RESULT',
    'Use the pattern SOURCE – PURPOSE – MAIN RESULT. Example: FORM – New Inquiry – Confirm + Tag + Notify. This makes workflows easy to identify.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why map the process before building?', 
    '["It is required by law","A clear plan makes building faster and reduces errors","It makes the workflow slower","It is not important"]'::jsonb,
    'A clear plan makes building faster and reduces errors',
    'Mapping the process before building creates a clear plan, making construction faster and reducing mistakes. It ensures you know what you want before you start building.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


