-- Insert Quiz Questions for Lesson: Create the Workflow and Trigger

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-workflow-trigger' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-workflow-trigger not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you create a workflow?', 
    '["Contacts → Import","Automations → Workflows","Settings → General","Dashboard → Widgets"]'::jsonb,
    'Automations → Workflows',
    'Workflows are created in Automations → Workflows. This is where you build, edit, and manage all automation sequences.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you keep the workflow in Draft while building?', 
    '["Draft workflows are faster","Draft does not respond to real triggers, so you can build safely","Draft is required by law","Published workflows cannot be edited"]'::jsonb,
    'Draft does not respond to real triggers, so you can build safely',
    'Keeping a workflow in Draft while building prevents it from responding to real trigger events. This lets you build and test safely before going live.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why does the Form Submitted trigger need a filter?', 
    '["It makes the workflow slower","It limits the workflow to the selected form and prevents unrelated submissions from starting it","It is not necessary","It deletes the form"]'::jsonb,
    'It limits the workflow to the selected form and prevents unrelated submissions from starting it',
    'Without a form filter, any form submission could trigger the workflow. The filter ensures only submissions from your specific form start this workflow.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


