-- Insert Quiz Questions for Lesson: Test, Inspect, and Correct

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'test-inspect-correct' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson test-inspect-correct not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the strongest test method?', 
    '["Just assume it works","Publish briefly and complete the real starting event with your own details","Never test workflows","Ask someone else to guess if it works"]'::jsonb,
    'Publish briefly and complete the real starting event with your own details',
    'The strongest test is to publish the workflow briefly and actually submit the form with your own details. This tests the real trigger and all actions in sequence.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three results to check?', 
    '["Only the confirmation email","Confirmation email, contact tag inquiry-new, and internal notification","Only the workflow name","Nothing needs to be checked"]'::jsonb,
    'Confirmation email, contact tag inquiry-new, and internal notification',
    'The three-result test checks: 1) Confirmation email arrived, 2) Contact has inquiry-new tag, 3) Internal notification was received. All three must pass.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if something fails?', 
    '["Give up and delete the workflow","Change one item at a time, save, and retest","Change everything at once","Ignore the failure"]'::jsonb,
    'Change one item at a time, save, and retest',
    'When troubleshooting, change one item at a time, save it, and repeat the full test. This helps identify exactly what was causing the problem.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


